'use strict';
let studioLibraryFilter={folder:'@all',query:'',limit:24};
let studioLibraryTab='prompts';
function studioValue(){return state.studio||PromptStudio.empty();}
function studioEdit(change){if(!state.studio)state.studio=PromptStudio.empty();change(state.studio);save();setText('#studio-save-state',storageOK?'이 브라우저에 저장됨':'저장되지 않음 · 백업으로 보관하세요');setText('#studio-modal-save',storageOK?'자동 저장됨':'저장되지 않음 · 백업으로 보관하세요');}
function studioOptions(options,value,blank='선택하지 않음'){return `<option value="">${esc(blank)}</option>${options.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}`;}
function studioFieldOptions(field){const c=ChoiceInputs.catalogs;return ({major:c.major,jobs:c.job,industries:c.industry,stacks:c.stack,languages:c.language.filter(v=>v!=='아직 정하지 않음'),frameworks:['Spring Boot','Django','FastAPI','Flask','Node.js','Express','NestJS','React','Next.js','Vue','Nuxt','Svelte','Angular','Flutter','React Native','TensorFlow','PyTorch']})[field.key]||field.options;}
function studioFieldHTML(field,scope='profile'){
  const profile=studioValue().profile,value=profile[field.key]??(field.type==='multi'?[]:''),id=`studio-${scope}-${field.key}`,options=studioFieldOptions(field),custom=field.type==='select'&&value&&!options.includes(value);
  let control;
  if(['select','multi'].includes(field.type))control=`<select id="${id}" data-studio-choice="${field.key}" data-scope="${scope}">${studioOptions(options,field.type==='multi'?'':custom?'__custom__':value,field.type==='multi'?'선택해서 추가':'선택하지 않음')}<option value="__custom__" ${custom?'selected':''}>직접 입력</option></select><div class="studio-custom" id="${id}-custom" ${custom?'':'hidden'}><label class="sr-only" for="${id}-text">${esc(field.label)} 직접 입력</label><input id="${id}-text" type="text" value="${esc(custom?value:'')}" placeholder="목록에 없는 항목">${field.type==='multi'?`<button type="button" class="secondary" id="${id}-add">추가</button>`:''}</div>${field.type==='multi'?`<ul class="choice-tags" id="${id}-tags" aria-label="선택한 ${esc(field.label)}">${value.map((v,i)=>`<li><span>${esc(v)}</span><button type="button" data-profile-remove="${i}" aria-label="${esc(v)} 선택 해제">×</button></li>`).join('')}</ul>`:''}`;
  else if(field.type==='textarea')control=`<textarea id="${id}" data-profile-field="${field.key}" data-scope="${scope}" rows="3">${esc(value)}</textarea>`;
  else control=`<input id="${id}" type="${field.type==='date'?'date':'text'}" data-profile-field="${field.key}" data-scope="${scope}" value="${esc(value)}">`;
  return `<div class="studio-field"><label for="${id}">${esc(field.label)}${field.type==='multi'?'<span class="tiny"> · 여러 개 선택</span>':''}</label>${control}</div>`;
}
function bindStudioProfileFields(scope='profile'){
  const commit=(key,value)=>{studioEdit(data=>data.profile[key]=value);refreshStudioLevels();};
  const entries=PromptStudio.fields;
  document.querySelectorAll(`[data-profile-field][data-scope="${scope}"]`).forEach(input=>input.oninput=()=>commit(input.dataset.profileField,input.value));
  for(const field of entries.filter(f=>['select','multi'].includes(f.type))){
    const id=`studio-${scope}-${field.key}`,select=$('#'+id);if(!select)continue;
    const custom=$('#'+id+'-custom'),input=$('#'+id+'-text');
    function tags(){
      if(field.type!=='multi')return;
      const list=$('#'+id+'-tags'),values=studioValue().profile[field.key]||[];
      list.innerHTML=values.map((v,i)=>`<li><span>${esc(v)}</span><button type="button" data-profile-remove="${i}" aria-label="${esc(v)} 선택 해제">×</button></li>`).join('');
      list.querySelectorAll('[data-profile-remove]').forEach(button=>button.onclick=()=>{const next=[...(studioValue().profile[field.key]||[])];next.splice(Number(button.dataset.profileRemove),1);commit(field.key,next);tags();select.focus({preventScroll:true});});
    }
    function add(value){const v=value.trim(),values=studioValue().profile[field.key]||[];if(!v)return;if(values.includes(v)){notify('이미 선택한 항목입니다.');return;}if(values.length>=200){notify('한 항목에서 200개까지 선택할 수 있습니다.');return;}commit(field.key,[...values,v]);tags();input.value='';}
    select.onchange=()=>{const own=select.value==='__custom__';custom.hidden=!own;if(own){if(field.type!=='multi')commit(field.key,input.value);input.focus({preventScroll:true});return;}if(field.type==='multi'){add(select.value);select.value='';}else commit(field.key,select.value);};
    if(field.type==='multi'){$('#'+id+'-add').onclick=()=>{add(input.value);input.focus({preventScroll:true});};input.onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();add(input.value);}};tags();}
    else input.oninput=()=>commit(field.key,input.value);
  }
}
function studioHeader(title,description,active){return `<div class="page-heading"><div><div class="eyebrow">MY SHARED INFORMATION</div><h1>${esc(title)}</h1><p class="sub">${esc(description)}</p></div></div><nav class="studio-local-nav" aria-label="공통 정보 관리"><a class="secondary ${active==='profile'?'selected':''}" href="#profile" ${active==='profile'?'aria-current="page"':''}>공통 프로필</a><a class="secondary ${active==='settings'?'selected':''}" href="#settings" ${active==='settings'?'aria-current="page"':''}>공통 AI 설정</a><a class="secondary" href="#notes">내 메모·프롬프트 보관함</a></nav><p class="tiny" id="studio-save-state" role="status">${storageOK?'입력한 내용은 이 브라우저에 자동 저장됩니다.':'저장 불가 · 백업으로 보관하세요'}</p>`;}

function studioProfileView(){
  nav('profile');$('#breadcrumb').innerHTML='공통 정보 <span>/</span> 프로필';
  const groups=[['education','학력·교육'],['skills','기술·개발 역량'],['career','희망 직무·지원 조건'],['experience','프로젝트·실무 경험'],['activities','자격·어학·기타 활동'],['personal','개인 역량·커리어']];
  $('#main').innerHTML=studioHeader('나의 공통 프로필','입력은 모두 선택입니다. 필요한 정보를 등록하고 프롬프트마다 가져올 항목을 고르세요.','profile')+`<section class="panel"><h2>기본 정보</h2><div class="studio-field-grid">${PromptStudio.fields.filter(f=>f.group==='basic').map(f=>studioFieldHTML(f)).join('')}</div></section>${groups.map(([group,label])=>`<details class="panel studio-details"><summary>${label}<span class="tiny">필요할 때 추가</span></summary><div class="studio-field-grid">${PromptStudio.fields.filter(f=>f.group===group).map(f=>studioFieldHTML(f)).join('')}</div>${group==='skills'?'<div id="studio-levels"></div>':''}${group==='experience'?'<div id="studio-projects"></div><button type="button" class="secondary" id="studio-add-project">프로젝트 추가 +</button>':''}</details>`).join('')}<div class="next-action"><a class="primary" href="#home">카테고리 선택하기 →</a><a class="secondary" href="#notes">저장한 프롬프트 보기</a></div>`;
  bindStudioProfileFields();refreshStudioLevels();renderStudioProjects();
  $('#studio-add-project').onclick=()=>{if((studioValue().profile.projects||[]).length>=100){notify('프로젝트는 100개까지 보관할 수 있습니다.');return;}studioEdit(data=>{const projects=data.profile.projects||(data.profile.projects=[]);projects.push({id:PromptStudio.newId(),name:'',period:'',role:'',technologies:'',results:'',evidence:''});});renderStudioProjects();$('#studio-projects article:last-child input')?.focus();};
}
function refreshStudioLevels(){
  const host=$('#studio-levels');if(!host)return;
  const p=studioValue().profile,names=[...new Set([...(p.languages||[]),...(p.stacks||[])])];
  host.innerHTML=names.length?`<h3>언어·기술 숙련도 <span class="tiny">선택 · 자기평가</span></h3><p class="tiny">이름을 선택한 것만으로 숙련도를 정하지 않습니다. 실제 사용 범위는 위에 기록하세요.</p><div class="studio-field-grid">${names.map((name,i)=>`<div class="studio-field"><label for="studio-level-${i}">${esc(name)}</label><select id="studio-level-${i}" data-skill-name="${esc(name)}">${['미평가','상','중','하'].map(v=>`<option value="${v}" ${(p.levels?.[name]||'미평가')===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div>`:'<p class="tiny">언어나 기술 스택을 선택하면 숙련도를 따로 기록할 수 있습니다.</p>';
  host.querySelectorAll('[data-skill-name]').forEach(select=>select.onchange=()=>studioEdit(data=>{data.profile.levels={...(data.profile.levels||{}),[select.dataset.skillName]:select.value};}));
}
function renderStudioProjects(){
  const host=$('#studio-projects');if(!host)return;
  host.innerHTML=(studioValue().profile.projects||[]).map(project=>`<article class="studio-project"><div class="studio-card-heading"><h3>${esc(project.name||'새 프로젝트')}</h3><button type="button" class="secondary" data-remove-project="${project.id}">프로젝트 삭제</button></div><div class="studio-field-grid">${[['name','프로젝트명'],['period','수행 기간'],['role','내 역할'],['technologies','사용 기술·개발 환경'],['results','주요 성과'],['evidence','확인 자료·한계']].map(([key,label])=>`<div class="studio-field"><label for="project-${project.id}-${key}">${label}</label><${['role','results','evidence'].includes(key)?'textarea':'input'} id="project-${project.id}-${key}" data-project="${project.id}" data-project-field="${key}" ${['role','results','evidence'].includes(key)?`rows="3">${esc(project[key])}</textarea>`:`type="text" value="${esc(project[key])}">`}</div>`).join('')}</div></article>`).join('');
  host.querySelectorAll('[data-project-field]').forEach(input=>input.oninput=()=>{studioEdit(data=>{const p=data.profile.projects.find(p=>p.id===input.dataset.project);p[input.dataset.projectField]=input.value;});});
  host.querySelectorAll('[data-remove-project]').forEach(button=>button.onclick=()=>{if(!window.confirm('이 프로젝트를 프로필에서 삭제할까요? 저장된 프롬프트의 내용은 유지됩니다.'))return;studioEdit(data=>data.profile.projects=data.profile.projects.filter(p=>p.id!==button.dataset.removeProject));renderStudioProjects();});
}
function studioSettingsView(){
  nav('settings');$('#breadcrumb').innerHTML='공통 정보 <span>/</span> AI 설정';
  const aiFields=Workbook.promptFields.filter(([key])=>typeof state.worksheets['0-1']?.[key]==='string'&&state.worksheets['0-1'][key].trim());
  $('#main').innerHTML=studioHeader('공통 AI 설정','역할·응답 방식·규칙을 저장하고, 프롬프트마다 필요한 항목만 선택하세요.','settings')+`<div class="studio-toolbar"><button class="primary" type="button" id="studio-add-rule">설정 항목 추가 +</button><button class="secondary" type="button" id="studio-default-rules">기본 규칙 가져오기</button><a class="text-button" href="#course/ai/1/write">AI 활용법의 지침 작성 보기 →</a></div><details class="panel studio-details"><summary>AI 활용법에서 작성한 항목 가져오기</summary><p>가져온 내용은 복사본으로 보관합니다. 기존 AI 활용법의 입력은 바뀌지 않습니다.</p>${aiFields.length?`<div class="studio-checks">${aiFields.map(([key,label])=>`<label><input type="checkbox" data-import-ai="${key}">${esc(label)}</label>`).join('')}</div><button class="secondary" type="button" id="studio-import-ai">선택한 항목 가져오기</button>`:'<p>아직 저장된 지침 항목이 없습니다. AI 활용법에서 작성하거나 위에서 새 설정을 추가하세요.</p>'}</details><div id="studio-rules"></div>`;
  $('#studio-add-rule').onclick=()=>{if(studioValue().rules.length>=200){notify('공통 설정은 200개까지 보관할 수 있습니다.');return;}studioEdit(data=>data.rules.push({id:PromptStudio.newId(),title:'새 설정',body:'',kind:'custom',categories:[],origin:'custom'}));renderStudioRules();$('#studio-rules article:last-child input')?.focus();};
  $('#studio-default-rules').onclick=()=>{studioEdit(data=>{for(const [title,body,kind] of [['사실 확인 규칙','제공한 자료만 사용하고 없는 경험·기술·성과를 만들지 마세요. 부족한 정보는 먼저 질문하세요.','rules'],['응답 언어','한국어로 답변하세요.','language'],['문체','간결하고 구체적인 문장으로 작성하세요.','tone']])if(data.rules.length<200&&!data.rules.some(r=>r.body===body))data.rules.push({id:PromptStudio.newId(),title,body,kind,categories:[],origin:'custom'});});renderStudioRules();notify('기본 규칙을 가져왔습니다. 프롬프트에 넣을 항목은 별도로 선택하세요.');};
  if($('#studio-import-ai'))$('#studio-import-ai').onclick=()=>{const selected=Array.from(document.querySelectorAll('[data-import-ai]:checked'),input=>input.dataset.importAi);if(!selected.length){notify('가져올 항목을 선택해 주세요.');return;}studioEdit(data=>{for(const key of selected){const [,title]=Workbook.promptFields.find(f=>f[0]===key),body=state.worksheets['0-1'][key];if(data.rules.length<200&&!data.rules.some(r=>r.title===title&&r.body===body))data.rules.push({id:PromptStudio.newId(),title,body,kind:key==='format'?'format':key==='rules'?'rules':'custom',categories:[],origin:'ai'});}});renderStudioRules();notify('선택한 항목을 공통 설정으로 복사했습니다.');};
  renderStudioRules();
}
function renderStudioRules(){
  const host=$('#studio-rules'),rules=studioValue().rules;
  host.innerHTML=rules.length?rules.map(rule=>`<article class="panel studio-rule"><div class="studio-card-heading"><span class="badge">${rule.origin==='ai'?'AI 활용법에서 가져옴':'공통 AI 설정'}</span><button class="secondary" type="button" data-delete-rule="${rule.id}">삭제</button></div><div class="studio-field-grid"><div class="studio-field"><label for="rule-title-${rule.id}">항목 이름</label><input id="rule-title-${rule.id}" value="${esc(rule.title)}" data-rule="${rule.id}" data-rule-field="title"></div><div class="studio-field"><label for="rule-kind-${rule.id}">종류</label><select id="rule-kind-${rule.id}" data-rule="${rule.id}" data-rule-field="kind">${[['role','역할'],['format','출력 형식'],['tone','문체'],['language','언어'],['length','분량'],['rules','작성 규칙'],['custom','직접 만든 항목']].map(([value,label])=>`<option value="${value}" ${rule.kind===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="studio-field"><label for="rule-body-${rule.id}">내용</label><textarea rows="4" id="rule-body-${rule.id}" data-rule="${rule.id}" data-rule-field="body">${esc(rule.body)}</textarea></div><fieldset class="studio-rule-categories"><legend>추천할 카테고리 · 선택하지 않으면 모두</legend>${PromptStudio.courseIds.map(id=>`<label><input type="checkbox" data-rule-category="${rule.id}" value="${id}" ${rule.categories.includes(id)?'checked':''}>${esc(courses.find(c=>c.id===id).name)}</label>`).join('')}</fieldset></article>`).join(''):'<div class="studio-empty">여러 작업에서 재사용할 규칙을 추가해 보세요. 설정 없이도 프롬프트를 만들 수 있습니다.</div>';
  host.querySelectorAll('[data-rule-field]').forEach(input=>{const apply=()=>studioEdit(data=>data.rules.find(r=>r.id===input.dataset.rule)[input.dataset.ruleField]=input.value);if(input.tagName==='SELECT')input.onchange=apply;else input.oninput=apply;});
  host.querySelectorAll('[data-rule-category]').forEach(input=>input.onchange=()=>studioEdit(data=>{const rule=data.rules.find(r=>r.id===input.dataset.ruleCategory);rule.categories=input.checked?[...new Set([...rule.categories,input.value])]:rule.categories.filter(c=>c!==input.value);}));
  host.querySelectorAll('[data-delete-rule]').forEach(button=>button.onclick=()=>{if(!window.confirm('이 공통 설정을 삭제할까요? 이미 저장한 프롬프트는 유지됩니다.'))return;studioEdit(data=>data.rules=data.rules.filter(r=>r.id!==button.dataset.deleteRule));renderStudioRules();});
}
function studioFolderOptions(value,includeAll=false){return `${includeAll?'<option value="@all">모든 폴더</option>':''}<option value="${includeAll?'@none':''}" ${value===(includeAll?'@none':'')?'selected':''}>미분류</option>${studioValue().folders.map(f=>`<option value="${includeAll?'folder:':''}${f.id}" ${(includeAll?'folder:':'')+f.id===value?'selected':''}>${esc(f.name)}</option>`).join('')}`;}
function studioLibraryView(legacyHTML){
  nav('notes');$('#breadcrumb').innerHTML='나의 워크스페이스 <span>/</span> 내 메모·프롬프트';
  const memoCount=allSteps.filter(step=>recordText(step).trim()).length;
  $('#main').innerHTML=`<div class="studio-library-heading"><div><h1>내 메모·프롬프트</h1><p class="sub">저장한 내용을 찾아 다시 사용하세요.</p></div><button class="primary" type="button" id="studio-library-new">새 프롬프트 +</button></div><div class="studio-library-tabs" role="group" aria-label="보관함 보기"><button type="button" id="studio-tab-prompts" aria-pressed="true">프롬프트 <span>${studioValue().prompts.length}</span></button><button type="button" id="studio-tab-notes" aria-pressed="false">학습 메모 <span>${memoCount}</span></button></div><section id="studio-new-panel" class="panel studio-new" hidden><div class="studio-card-heading"><h2>어떤 프롬프트를 만들까요?</h2><button class="secondary" type="button" id="studio-new-cancel">닫기</button></div><div class="studio-toolbar"><div class="studio-field"><label for="studio-new-course">카테고리</label><select id="studio-new-course">${PromptStudio.courseIds.map(id=>`<option value="${id}">${esc(courses.find(c=>c.id===id).name)}</option>`).join('')}</select></div><div class="studio-field"><label for="studio-new-step">작업</label><select id="studio-new-step"></select></div><button class="primary" type="button" id="studio-new-prompt">작성 시작 →</button></div><p class="tiny">작성 중인 구성이 있으면 이어서 엽니다.</p></section><details class="studio-library-management"><summary>폴더·설정 관리</summary><div class="panel"><details class="studio-details studio-folder-management"><summary>폴더 만들기·변경</summary><div class="studio-toolbar"><div class="studio-field"><label for="studio-folder-manage">관리할 폴더</label><select id="studio-folder-manage"><option value="">새 폴더</option>${studioValue().folders.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></div><div class="studio-field"><label for="studio-folder-name">폴더 이름</label><input id="studio-folder-name" maxlength="100"></div><button class="secondary" type="button" id="studio-create-folder">새 폴더 생성</button><button class="secondary" type="button" id="studio-rename-folder">이름 변경</button><button class="secondary" type="button" id="studio-delete-folder">폴더 삭제</button></div><p class="tiny">폴더를 삭제해도 프롬프트는 미분류에 남습니다.</p></details><div class="studio-local-nav"><button class="secondary" type="button" data-open-profile>내 정보</button><a class="secondary" href="#profile">프로필 상세 관리</a><a class="secondary" href="#settings">공통 AI 설정</a><button class="secondary" type="button" id="download-notes">문서 내려받기</button><a class="secondary" href="#backup">백업·복원</a></div></div></details><section id="studio-prompt-panel"><div class="studio-toolbar studio-library-filters"><div class="studio-field"><label class="sr-only" for="studio-folder-filter">폴더</label><select id="studio-folder-filter">${studioFolderOptions(studioLibraryFilter.folder,true)}</select></div><div class="studio-field studio-search"><label class="sr-only" for="studio-search">프롬프트 검색</label><input id="studio-search" type="search" value="${esc(studioLibraryFilter.query)}" placeholder="프롬프트 검색"></div></div><p id="studio-library-count" class="tiny" role="status"></p><div id="studio-library-items"></div><div id="studio-draft-list"></div></section><section id="studio-notes-panel" hidden>${legacyHTML}</section><p id="studio-save-state" class="tiny" role="status">이 브라우저에 자동 저장됩니다.</p>`;
  const updateSteps=()=>{const c=courses.find(c=>c.id===$('#studio-new-course').value);$('#studio-new-step').innerHTML=c.steps.map(step=>`<option value="${step.id}" ${step.id==='1-2'?'selected':''}>${esc(step.title)}</option>`).join('');};$('#studio-new-course').value='company';updateSteps();
  $('#studio-new-course').onchange=updateSteps;$('#studio-new-prompt').onclick=()=>studioGo(`#compose/${$('#studio-new-course').value}/${$('#studio-new-step').value}`);
  $('#studio-library-new').onclick=()=>{setStudioLibraryTab('prompts');$('#studio-new-panel').hidden=false;$('#studio-new-course').focus({preventScroll:true});};
  $('#studio-new-cancel').onclick=()=>{$('#studio-new-panel').hidden=true;$('#studio-library-new').focus({preventScroll:true});};
  $('#studio-tab-prompts').onclick=()=>setStudioLibraryTab('prompts');$('#studio-tab-notes').onclick=()=>setStudioLibraryTab('notes');
  setStudioLibraryTab(studioLibraryTab);
  $('#download-notes').onclick=download;
  $('#studio-folder-manage').onchange=()=>{$('#studio-folder-name').value=studioValue().folders.find(f=>f.id===$('#studio-folder-manage').value)?.name||'';};
  const refresh=(selectedId='')=>Viewport.keep(()=>{notesView();const select=$('#studio-folder-manage');select.closest('details').open=true;$('.studio-library-management').open=true;select.value=selectedId;$('#studio-folder-name').value=studioValue().folders.find(f=>f.id===selectedId)?.name||'';});
  function folderName(excludeId=''){const name=$('#studio-folder-name').value.trim();if(!name){notify('폴더 이름을 입력해 주세요.');return null;}if(studioValue().folders.some(f=>f.name===name&&f.id!==excludeId)){notify('같은 이름의 폴더가 있습니다.');return null;}return name;}
  $('#studio-create-folder').onclick=()=>{if(studioValue().folders.length>=200){notify('폴더는 200개까지 만들 수 있습니다.');return;}const name=folderName();if(!name)return;const id=PromptStudio.newId();studioEdit(data=>data.folders.push({id,name}));refresh(id);};
  $('#studio-rename-folder').onclick=()=>{const id=$('#studio-folder-manage').value;if(!id){notify('이름을 바꿀 폴더를 선택해 주세요.');return;}const name=folderName(id);if(!name)return;studioEdit(data=>data.folders.find(f=>f.id===id).name=name);refresh(id);};
  $('#studio-delete-folder').onclick=()=>{const id=$('#studio-folder-manage').value;if(!id){notify('삭제할 폴더를 선택해 주세요.');return;}if(!window.confirm('폴더를 삭제하고 안의 프롬프트를 미분류로 옮길까요?'))return;studioEdit(data=>PromptStudio.removeFolder(data,id));studioLibraryFilter.folder='@all';refresh();};
  $('#studio-folder-filter').value=studioLibraryFilter.folder;$('#studio-folder-filter').onchange=e=>{studioLibraryFilter.folder=e.target.value;studioLibraryFilter.limit=24;renderStudioLibraryItems();};
  $('#studio-search').oninput=e=>{studioLibraryFilter.query=e.target.value;studioLibraryFilter.limit=24;renderStudioLibraryItems();};renderStudioLibraryItems();renderStudioDraftList();
}
function renderStudioLibraryItems(){
  const data=studioValue(),query=studioLibraryFilter.query.trim().toLocaleLowerCase(),folder=studioLibraryFilter.folder;
  setText('#studio-tab-prompts span',String(data.prompts.length));
  const filtered=data.prompts.filter(p=>(folder==='@all'||p.folderId===(folder==='@none'?'':folder.slice(7)))&&(!query||(p.name+'\n'+PromptStudio.output(p)).toLocaleLowerCase().includes(query))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
  const shown=filtered.slice(0,studioLibraryFilter.limit);setText('#studio-library-count',`${filtered.length}개 프롬프트 · ${shown.length}개 표시`);
  $('#studio-library-items').innerHTML=shown.length?`<div class="studio-library-grid">${shown.map(p=>`<article class="panel studio-saved"><div class="studio-saved-row"><div class="studio-saved-title"><h2><a href="#compose/${p.courseId}/${p.stepId}/${p.id}">${esc(p.name)}</a></h2><p class="tiny">${esc(courses.find(c=>c.id===p.courseId).name)} · ${esc(data.folders.find(f=>f.id===p.folderId)?.name||'미분류')}</p></div><div class="studio-saved-actions"><a class="secondary" href="#compose/${p.courseId}/${p.stepId}/${p.id}">열기</a><button class="secondary" type="button" data-copy-saved="${p.id}">복사</button></div></div><details class="studio-saved-options"><summary>더 보기</summary><div class="studio-field-grid"><div class="studio-field"><label for="saved-name-${p.id}">이름 변경</label><input id="saved-name-${p.id}" data-saved-name="${p.id}" value="${esc(p.name)}"></div><div class="studio-field"><label for="saved-folder-${p.id}">폴더 이동</label><select id="saved-folder-${p.id}" data-saved-folder="${p.id}">${studioFolderOptions(p.folderId)}</select></div></div><details class="studio-saved-preview"><summary>내용 미리보기</summary><label class="sr-only" for="saved-preview-${p.id}">저장한 프롬프트 내용</label><textarea id="saved-preview-${p.id}" rows="8" readonly>${esc(PromptStudio.output(p))}</textarea></details><div class="studio-toolbar"><button class="secondary" type="button" data-duplicate-saved="${p.id}">복제</button><button class="secondary" type="button" data-delete-saved="${p.id}">삭제</button></div></details></article>`).join('')}</div>${shown.length<filtered.length?'<button class="secondary" type="button" id="studio-more">더 보기</button>':''}`:`<div class="studio-empty"><p>${query||folder!=='@all'?'검색 결과가 없습니다.':'아직 저장한 프롬프트가 없습니다.'}</p><button class="secondary" type="button" id="studio-empty-create">새 프롬프트 만들기</button></div>`;
  if($('#studio-empty-create'))$('#studio-empty-create').onclick=()=>$('#studio-library-new').click();
  document.querySelectorAll('[data-saved-name]').forEach(input=>input.onchange=()=>{const p=studioValue().prompts.find(p=>p.id===input.dataset.savedName);if(!input.value.trim()){input.value=p.name;notify('이름은 비워 둘 수 없습니다.');return;}studioEdit(()=>{const oldName=p.name;p.name=input.value.trim();input.closest('.studio-saved').querySelector('h2 a').textContent=p.name;for(const draft of Object.values(studioValue().drafts))if(draft.sourcePromptId===p.id&&draft.name===oldName)draft.name=p.name;p.updatedAt=new Date().toISOString();});});
  document.querySelectorAll('[data-saved-folder]').forEach(select=>select.onchange=()=>{studioEdit(data=>{const p=data.prompts.find(p=>p.id===select.dataset.savedFolder),old=p.folderId;p.folderId=select.value;for(const draft of Object.values(data.drafts))if(draft.sourcePromptId===p.id&&draft.folderId===old)draft.folderId=select.value;});renderStudioLibraryItems();});
  document.querySelectorAll('[data-copy-saved]').forEach(button=>button.onclick=async()=>{const prompt=studioValue().prompts.find(p=>p.id===button.dataset.copySaved),text=PromptStudio.output(prompt);try{await navigator.clipboard.writeText(text);notify('복사했습니다.');}catch{const target=$('#saved-preview-'+prompt.id);Viewport.keep(()=>{for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;target.focus({preventScroll:true});target.select();});notify('내용을 선택했습니다. 복사 단축키를 눌러 주세요.');}});
  document.querySelectorAll('[data-duplicate-saved]').forEach(button=>button.onclick=()=>{try{studioEdit(data=>PromptStudio.duplicate(data,button.dataset.duplicateSaved));renderStudioLibraryItems();notify('독립된 복사본을 저장했습니다.');}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-delete-saved]').forEach(button=>button.onclick=()=>{if(!window.confirm('저장된 프롬프트와 이 프롬프트의 작성 중 구성을 삭제할까요? 다른 복사본과 학습 기록은 유지됩니다.'))return;studioEdit(data=>{data.prompts=data.prompts.filter(p=>p.id!==button.dataset.deleteSaved);delete data.drafts['saved-'+button.dataset.deleteSaved];});renderStudioLibraryItems();renderStudioDraftList();});
  if($('#studio-more'))$('#studio-more').onclick=()=>{studioLibraryFilter.limit+=24;renderStudioLibraryItems();};
}
function studioGo(hash){navigateTo(hash,{start:true});$('#main').focus({preventScroll:true});}

function renderStudioDraftList(){
  const host=$('#studio-draft-list');if(!host)return;
  const drafts=Object.entries(studioValue().drafts);
  host.innerHTML=drafts.length?`<details class="panel studio-details"><summary>작성 중인 프롬프트 구성 ${drafts.length}개</summary><ul class="studio-draft-list">${drafts.map(([key,d])=>`<li><a class="text-button" href="#compose/${d.courseId}/${d.stepId}${d.sourcePromptId?'/'+d.sourcePromptId:''}">${esc(d.name||'작성 중인 구성')}</a><button type="button" class="secondary" data-delete-draft="${key}">작성 중 구성 삭제</button></li>`).join('')}</ul></details>`:'';
  host.querySelectorAll('[data-delete-draft]').forEach(button=>button.onclick=()=>{if(!window.confirm('작성 중인 구성만 삭제할까요? 보관함에 저장한 프롬프트와 학습 기록은 유지됩니다.'))return;studioEdit(data=>delete data.drafts[button.dataset.deleteDraft]);renderStudioDraftList();});
}

let studioProfileModalContext=null;
function openStudioProfileModal(opener=document.activeElement){
  const dialog=$('#studio-profile-dialog');if(!dialog||dialog.open)return;
  studioProfileModalContext={opener,position:Viewport.capture(),hash:location.hash,overflow:document.body.style.overflow};
  dialog.innerHTML=`<div class="studio-modal-heading"><div><h2 id="studio-profile-title">내 정보 선택하기</h2><p>필요한 것만 선택하세요. 나중에 바꿀 수 있어요.</p></div><button class="secondary studio-modal-close" id="studio-modal-close" type="button" aria-label="내 정보 선택 닫기">×</button></div><div class="studio-modal-body"><div class="studio-field-grid">${PromptStudio.fields.filter(f=>f.group==='basic').map(f=>studioFieldHTML(f,'modal')).join('')}</div></div><div class="studio-modal-footer"><span class="tiny" id="studio-modal-save" role="status">${storageOK?'선택한 정보는 자동 저장됩니다.':'저장 불가 · 백업으로 보관하세요'}</span><button class="primary" id="studio-modal-done" type="button">선택 완료</button></div>`;
  bindStudioProfileFields('modal');
  $('#studio-modal-close').onclick=()=>closeStudioProfileModal();$('#studio-modal-done').onclick=()=>closeStudioProfileModal();
  dialog.oncancel=event=>{event.preventDefault();closeStudioProfileModal();};
  dialog.onclick=event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeStudioProfileModal();};
  dialog.onclose=()=>{if(studioProfileModalContext)closeStudioProfileModal();};
  document.body.style.overflow='hidden';dialog.showModal();$('#studio-modal-major')?.focus({preventScroll:true});
}
function closeStudioProfileModal(restore=true){
  const context=studioProfileModalContext;if(!context)return;studioProfileModalContext=null;
  const dialog=$('#studio-profile-dialog');if(dialog?.open)dialog.close();document.body.style.overflow=context.overflow;
  if(restore&&location.hash===context.hash){
    if(activePage==='compose'&&studioEditor)rerenderStudioParts();
    window.scrollTo({left:context.position.x,top:context.position.y,behavior:'instant'});
    if(context.opener?.isConnected)context.opener.focus({preventScroll:true});
  }
}

function setStudioLibraryTab(tab){
  studioLibraryTab=tab;
  $('#studio-prompt-panel').hidden=tab!=='prompts';$('#studio-notes-panel').hidden=tab!=='notes';
  $('#studio-tab-prompts').setAttribute('aria-pressed',String(tab==='prompts'));$('#studio-tab-notes').setAttribute('aria-pressed',String(tab==='notes'));
  $('#studio-library-new').hidden=tab==='notes';if(tab==='notes')$('#studio-new-panel').hidden=true;
}
